{"path":"game/scripts/game_manager.gd","content":"extends Node2D
class_name GameManager

const TILE_SIZE: int = 32

@export var arena_scenes: Array = []
@export var snake_scene: PackedScene
@export var orb_scene: PackedScene
@export var hazard_scene: PackedScene
@export var ui_scene: PackedScene

var arena_index: int = 0
var arena_inst: Node = null
var snake: Node = null
var orb_manager: Node = null
var hazards: Array = []
var ui: Node = null

var score: int = 0
var orbs_eaten: int = 0
var speed_level: int = 0
var base_move_interval: float = 0.20
var move_interval: float = 0.20
var game_over: bool = false

func _ready() -> void:
    OS.window_title = "Neon Serpent"
    randomize()
    _ensure_input_actions()
    # preload scenes if not provided via export
    if arena_scenes.empty():
        arena_scenes = [preload("res://game/scenes/arena_1.tscn"), preload("res://game/scenes/arena_2.tscn"), preload("res://game/scenes/arena_3.tscn")]
    if not snake_scene:
        snake_scene = preload("res://game/scenes/snake.tscn")
    if not orb_scene:
        orb_scene = preload("res://game/scenes/orb.tscn")
    if not hazard_scene:
        hazard_scene = preload("res://game/scenes/hazard_ball.tscn")
    if not ui_scene:
        ui_scene = preload("res://game/scenes/ui.tscn")

    _load_ui()
    _load_arena(arena_index)
    start_run()

func _ensure_input_actions() -> void:
    var actions = {
        "move_up": [KEY_UP, KEY_W],
        "move_down": [KEY_DOWN, KEY_S],
        "move_left": [KEY_LEFT, KEY_A],
        "move_right": [KEY_RIGHT, KEY_D],
        "restart": [KEY_R],
        "quit": [KEY_ESCAPE]
    }
    for name in actions.keys():
        if not InputMap.has_action(name):
            InputMap.add_action(name)
        # add keys even if action exists
        for kc in actions[name]:
            var ev = InputEventKey.new()
            ev.physical_keycode = kc
            InputMap.action_add_event(name, ev)

func _load_ui() -> void:
    if ui:
        ui.queue_free()
        ui = null
    ui = ui_scene.instantiate()
    add_child(ui)
    # UIController should exist on the scene
    if ui.has_method("update_score"):
        ui.update_score(score)
        ui.update_speed(speed_level)

func _load_arena(index: int) -> void:
    clear_hazards()
    if arena_inst:
        arena_inst.queue_free()
        arena_inst = null
    arena_inst = arena_scenes[index].instantiate()
    add_child(arena_inst)
    # setup orb manager
    if not orb_manager:
        orb_manager = OrbManager.new()
        add_child(orb_manager)
    orb_manager.setup(arena_inst, orb_scene)
    # spawn hazards
    _spawn_hazards_from_arena(arena_inst)

func _spawn_hazards_from_arena(arena_root: Node) -> void:
    clear_hazards()
    if arena_root.has_node("HazardSpawns"):
        for p in arena_root.get_node("HazardSpawns").get_children():
            if p is Position2D:
                var h = hazard_scene.instantiate()
                h.position = p.global_position
                if h.has_method("set" ):
                    pass
                # set bounds for hazard
                if h is Node2D and h.has_method("set"):
                    pass
                if h.has_variable("bounds"):
                    h.bounds = Rect2(0,0,1280,720)
                add_child(h)
                hazards.append(h)

func clear_hazards() -> void:
    for h in hazards:
        if is_instance_valid(h):
            h.queue_free()
    hazards.clear()

func start_run() -> void:
    score = 0
    orbs_eaten = 0
    speed_level = 0
    move_interval = base_move_interval
    game_over = false
    if ui:
        ui.hide_game_over()
        ui.update_score(score)
        ui.update_speed(speed_level)
    # spawn snake
    if snake:
        snake.queue_free()
        snake = null
    snake = snake_scene.instantiate()
    add_child(snake)
    # connect signals
    if snake.has_signal("moved_to"):
        snake.connect("moved_to", Callable(self, "_on_snake_moved"))
    if snake.has_signal("died"):
        snake.connect("died", Callable(self, "_on_snake_died"))
    # start movement
    if snake.has_method("start"):
        snake.start(move_interval)

func _on_snake_moved(new_pos: Vector2i) -> void:
    if game_over:
        return
    # check wall bounds
    if is_blocked(new_pos):
        # notify snake of external die
        if snake.has_method("_on_external_die"):
            snake._on_external_die()
        else:
            if snake.has_method("stop"):
                snake.stop()
        return
    # check hazards
    for h in hazards:
        if is_instance_valid(h):
            var grid_h = Vector2i(int(round(h.global_position.x / TILE_SIZE)), int(round(h.global_position.y / TILE_SIZE)))
            if grid_h == new_pos:
                if snake.has_method("_on_external_die"):
                    snake._on_external_die()
                else:
                    if snake.has_method("stop"):
                        snake.stop()
                return
    # check orb
    if orb_manager and orb_manager.consume_at(new_pos):
        orbs_eaten += 1
        score += 10
        if ui and ui.has_method("update_score"):
            ui.update_score(score)
        if snake and snake.has_method("grow"):
            snake.grow()
        # speed up every 5 orbs
        if orbs_eaten % 5 == 0:
            speed_level += 1
            move_interval = max(0.05, base_move_interval - float(speed_level) * 0.02)
            if snake and snake.has_method("start"):
                snake.start(move_interval)
            if ui and ui.has_method("update_speed"):
                ui.update_speed(speed_level)
            if ui and ui.has_method("pulse_background"):
                ui.pulse_background()
        # win check
        if score >= 100:
            print("WIN")
            _advance_arena()

func _advance_arena() -> void:
    arena_index = (arena_index + 1) % arena_scenes.size()
    _load_arena(arena_index)
    # restart snake in new arena
    if snake and snake.has_method("reset_state"):
        snake.reset_state()
    # reset orb manager
    if orb_manager:
        orb_manager.clear_all()
        orb_manager.setup(arena_inst, orb_scene)

func is_blocked(grid_pos: Vector2i) -> bool:
    # block if outside bounds
    var max_x = int(1280 / TILE_SIZE) - 1
    var max_y = int(720 / TILE_SIZE) - 1
    if grid_pos.x < 0 or grid_pos.y < 0 or grid_pos.x > max_x or grid_pos.y > max_y:
        return true
    # check arena Walls node
    if arena_inst and arena_inst.has_node("Walls"):
        for w in arena_inst.get_node("Walls").get_children():
            if w is Position2D:
                var gw = Vector2i(int(round(w.global_position.x / TILE_SIZE)), int(round(w.global_position.y / TILE_SIZE)))
                if gw == grid_pos:
                    return true
    return false

func _on_snake_died() -> void:
    if game_over:
        return
    game_over = true
    print("GAME OVER")
    print(str(score))
    if ui and ui.has_method("show_game_over"):
        ui.show_game_over(score)

func _process(delta: float) -> void:
    if game_over:
        if Input.is_action_just_pressed("restart"):
            reset_game()
        elif Input.is_action_just_pressed("quit"):
            get_tree().quit()

func reset_game() -> void:
    # reload arena and UI
    _load_arena(arena_index)
    start_run()
